function rc144OpenAll(kind,memberId){
 const d=document.createElement('dialog');d.className='rc144-modal';
 let title='',items=[];
 if(kind==='owner'){
   title='Todas as conquistas';
   const r=loadOwnerRewards();
   const art=['','','',''];
   items=r.map((x,i)=>({name:x.name,sub:x.description||'Conquista BERTH.A',art:art[i%art.length]}));
 }else if(kind==='kids'){
   title='Todas as premiações Kids';
   const cfg=kidsRewardsFor(memberId);
   const art={medal:'',trophy:'',skin:'',egg:'',companion:''};
   items=Object.values(cfg).map(x=>({name:x.name||'Conquista',sub:`${Math.max(1,+x.points||1)} pontos · ${x.type||'medal'}`,art:art[x.type]||''}));
 }else{
   title='Todos os reconhecimentos';
   const p=loadRecognitionPresets();
   const art=['','','','',''];
   items=p.map((x,i)=>({name:x.name,sub:x.message||'',art:art[i%art.length]}));
 }
 d.innerHTML=`<div class="rc144-modal-card"><div class="rc144-modal-head"><div><div class="eyebrow">PREMIAÇÕES</div><h3>${escapeHtml(title)}</h3></div><button type="button" class="rc144-modal-close">×</button></div><div class="rc144-modal-list">${items.map(x=>`<div class="rc144-modal-item">${rc144Img(x.art)}<div><strong>${escapeHtml(x.name)}</strong><small>${escapeHtml(x.sub)}</small></div></div>`).join('')}</div></div>`;
 document.body.appendChild(d);d.querySelector('.rc144-modal-close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close()});d.onclose=()=>d.remove();d.showModal();
}

function renderRewardsRC144(){
 ensureSatelliteStyles();ensureSatelliteIdentityV4();rc144Styles();
 const data=loadSatellites(),kids=(data.members||[]).filter(m=>m.status!=='removed'&&m.role==='kids');
 const owner=loadOwnerRewards(),presets=loadRecognitionPresets(),progress=loadKidsProgress(),themes=loadKidsRewardThemes();
 let selectedId=window.berthaHmlStorage.getItem('bertha.rewards.selected.kid')||kids[0]?.id||'';
 let kid=kids.find(x=>String(x.id)===String(selectedId))||kids[0];
 if(kid)selectedId=kid.id;
 const kp=kid?(progress[kid.id]||{season:0,lifetime:0,awards:[],log:[]}):{season:0,lifetime:0,awards:[],log:[]};
 const cfg=kid?kidsRewardsFor(kid.id):{};
 const cfgVals=Object.values(cfg),next=cfgVals.filter(r=>r.active!==false&&(+r.points||0)>(+kp.season||0)).sort((a,b)=>(+a.points||0)-(+b.points||0))[0];
 const level=Math.max(1,Math.floor((+kp.season||0)/100)+1),levelPct=((+kp.season||0)%100),toNext=100-levelPct;
 const medalCount=(kp.awards||[]).filter(a=>a.type==='medal').length,trophyCount=(kp.awards||[]).filter(a=>a.type==='trophy').length,skinCount=(kp.awards||[]).filter(a=>a.type==='skin').length,streak=rc144KidStreak(kp.log);
 const theme=kid?(themes[kid.id]||'mist'):'mist';
 const ownerTiles=[
   ['','1 semana consistente','Há 2 dias'],['','Rotina em dia','Há 1 semana'],['','Foco de 30 dias','Há 3 semanas'],['','Escolhas mais conscientes','Há 1 mês']
 ];
 const kidTiles=[
   ['','Explorador','Curioso por natureza'],['','Super Leitor','3 livros lidos'],['','Boa Escolha','Atitude incrível'],['','Coração Gentil','Ajudou alguém']
 ];
 const themeButtons=['mist','ocean','space','forest','solar','coral'].map(t=>`<button type="button" class="rc144-theme ${t===theme?'active':''}" data-theme="${t}">${({mist:'Azul Neblina',ocean:'Oceano',space:'Espaço',forest:'Floresta',solar:'Solar',coral:'Coral'})[t]}</button>`).join('');
 const defaultEditor=cfgVals[0]||{name:'Missão de Estrela',points:50,type:'medal',active:true,criterion:'weekly'};
 app.innerHTML=`<div class="rc144-page">
 <section class="sat-hero sat-ideal-hero rc144-hero"><div class="sat-hero-copy"><div class="eyebrow">PREMIAÇÕES</div><h2>Você desempenha.<br>A BERTH.A reconhece.</h2><p>Conquistas para você. Gamificação para Kids. Reconhecimento para quem caminha junto.</p></div><div class="rc144-bars"><i></i><i></i><i></i></div></section>
 <div class="rc144-tabs"><button class="active" data-pane="owner">Owner</button><button data-pane="kids">Kids</button><button data-pane="helpers">Reconhecimentos</button></div>

 <section class="rc144-pane" data-rc144-pane="owner">
   <section class="rc144-section"><div class="rc144-head"><div><h3>Minhas conquistas</h3><p>Pequenas vitórias, grandes movimentos. Continue assim!</p></div><button type="button" class="rc144-more" data-see-all="owner">Ver todas ›</button></div>
   <div class="rc144-grid4">${ownerTiles.map(x=>`<div class="rc144-tile">${rc144Img(x[0])}<strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}</div>
   <details class="rc144-config"><summary>Personalizar conquistas</summary><div class="rc144-config-body">${owner.map((r,i)=>`<div class="reward-config-card" data-owner-reward="${i}"><div class="reward-config-head"><span class="reward-config-icon">${escapeHtml(r.icon||'✦')}</span><div><strong>${escapeHtml(r.name)}</strong><small>${escapeHtml(r.description||'')}</small></div><label class="reward-active"><input type="checkbox" data-or-active ${r.active!==false?'checked':''}>Ativa</label></div><div class="reward-form-grid"><label>Nome<input data-or-name value="${escapeHtml(r.name)}"></label><label>Ícone<input data-or-icon value="${escapeHtml(r.icon||'✦')}"></label><label>Critério<select data-or-criterion><option value="progress100" ${r.criterion==='progress100'?'selected':''}>Progresso em 100%</option><option value="goal" ${r.criterion==='goal'?'selected':''}>Meta concluída</option><option value="streak" ${r.criterion==='streak'?'selected':''}>Sequência de dias</option><option value="cycle" ${r.criterion==='cycle'?'selected':''}>Ciclo concluído</option></select></label><label>Valor/meta<input type="number" min="1" data-or-value value="${Math.max(1,+r.value||1)}"></label><label>Recorrência<select data-or-rec><option value="once" ${r.recurrence==='once'?'selected':''}>Única</option><option value="each" ${r.recurrence==='each'?'selected':''}>A cada conquista</option><option value="weekly" ${r.recurrence==='weekly'?'selected':''}>Semanal</option><option value="monthly" ${r.recurrence==='monthly'?'selected':''}>Mensal</option></select></label><label>Visual<input data-or-visual value="${escapeHtml(r.visual||'Selo BERTH.A')}"></label></div><label>Descrição<input data-or-desc value="${escapeHtml(r.description||'')}"></label></div>`).join('')}<div class="reward-config-actions"><button id="rc144SaveOwner">Salvar conquistas</button></div></div></details>
   </section>
 </section>

 <section class="rc144-pane" data-rc144-pane="kids" hidden>
   ${kid?`<section class="rc144-section"><div class="rc144-head"><div><h3>Conquistas da sua Kids</h3><p>Acompanhe o progresso e celebre cada conquista.</p></div><select id="rc144KidSelect" style="min-height:36px;border-radius:999px;border:1px solid rgba(126,115,132,.1);background:#fff;padding:0 12px;font-size:12px">${kids.map(k=>`<option value="${k.id}" ${String(k.id)===String(kid.id)?'selected':''}>${escapeHtml(k.name)}</option>`).join('')}</select></div>
   <div class="rc144-kid-profile"><span class="rc144-avatar">${satelliteAvatarIcon(kid.avatarKey||'son')}</span><div><h4>${escapeHtml(kid.name)}</h4><p>${next?`${Math.max(0,(+next.points||0)-(+kp.season||0))} pontos para ${escapeHtml(next.name||'a próxima conquista')}`:'Todas as metas atuais alcançadas.'}</p><div class="rc144-level"><span style="width:${levelPct}%"></span></div><p style="display:flex;justify-content:space-between;margin-top:5px"><span>Nível ${level}</span><span>${toNext} pontos para o próximo nível</span></p></div><span class="rc144-points">★ ${+kp.season||0} pontos</span></div>
   <div class="rc144-stats"><div class="rc144-stat">${rc144Img('')}<div><strong>Medalhas</strong><small>${medalCount}/${Object.values(cfg).filter(r=>r.type==='medal').length||1}</small></div></div><div class="rc144-stat">${rc144Img('')}<div><strong>Troféus</strong><small>${trophyCount}/${Object.values(cfg).filter(r=>r.type==='trophy').length||1}</small></div></div><div class="rc144-stat">${rc144Img('')}<div><strong>Skins</strong><small>${skinCount}/${Object.values(cfg).filter(r=>r.type==='skin').length||1}</small></div></div><div class="rc144-stat">${rc144Img('')}<div><strong>Streak</strong><small>${streak} dias</small></div></div></div>
   <div class="rc144-head" style="margin-top:14px;margin-bottom:0"><div><h3 style="font-size:15px">Coleção</h3></div><button type="button" class="rc144-more" data-see-all="kids">Ver todas ›</button></div>
   <div class="rc144-grid4" style="margin-top:10px">${kidTiles.map(x=>`<div class="rc144-tile kid">${rc144Img(x[0])}<strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}</div>
   <div class="rc144-theme-wrap"><div class="rc144-theme-title"><div><strong>Temas de recompensa</strong><small>Personalize a coleção dos Kids</small></div><span>›</span></div><div class="rc144-themes">${themeButtons}</div></div>
   </section>
   <section class="rc144-section"><div class="rc144-head"><div><h3>Configurar novas premiações</h3><p>Personalize as regras e crie recompensas incríveis para ${escapeHtml(kid.name)}.</p></div><button class="rc144-add" id="rc144NewReward">＋ Nova premiação</button></div>
   <div class="rc144-config-card"><div class="rc144-config-title"><div><h4 id="rc144EditorTitle">${escapeHtml(defaultEditor.name||'Missão de Estrela')}</h4><p>Defina pontos, meta e o que será desbloqueado.</p></div><label class="reward-active"><input id="rc144RewardActive" type="checkbox" ${defaultEditor.active!==false?'checked':''}>Ativa</label></div>
   <div class="rc144-reward-editor">${rc144Img('','hero-art')}<div class="rc144-fields"><label>Nome da premiação<input id="rc144RewardName" value="${escapeHtml(defaultEditor.name||'Missão de Estrela')}"></label><div class="rc144-mini-grid"><label>Pontos / meta<input id="rc144RewardPoints" type="number" min="1" value="${Math.max(1,+defaultEditor.points||50)}"></label><label>Tipo<select id="rc144RewardType"><option value="medal">Medalha</option><option value="trophy">Troféu</option><option value="egg">Cápsula</option><option value="skin">Skin</option><option value="companion">Personagem</option></select></label><label>Critério<select id="rc144RewardCriterion"><option value="points">Atingir pontos</option><option value="weekly">Concluir missões da semana</option><option value="streak">Sequência de dias</option><option value="mission">Missão específica</option></select></label></div></div></div>
   <div style="margin-top:12px"><span style="font-size:10.5px;color:#817984">Ícone da premiação</span><div class="rc144-icon-picks" style="margin-top:7px">${['','','','','','','',''].map((a,i)=>`<button type="button" data-art="${a}" class="${i===0?'active':''}">${rc144Img(a)}</button>`).join('')}</div></div>
   <div class="reward-config-actions" style="margin-top:12px"><button id="rc144SaveKidReward">Salvar premiação</button></div></div>
   <div class="rc144-highlights"><div class="rc144-highlight">${rc144Img('')}<div><strong>Medalhas</strong><small>Colecione e evolua</small></div></div><div class="rc144-highlight">${rc144Img('')}<div><strong>Troféus</strong><small>Grandes conquistas</small></div></div><div class="rc144-highlight">${rc144Img('')}<div><strong>Skins</strong><small>Personalize a jornada</small></div></div><div class="rc144-highlight">${rc144Img('')}<div><strong>Missão da semana</strong><small>Desafios especiais</small></div></div></div>
   </section>`:`<section class="rc144-section"><div class="sat-empty">Cadastre um satélite como Kids para configurar a gamificação.</div></section>`}
 </section>

 <section class="rc144-pane" data-rc144-pane="helpers" hidden>
   <section class="rc144-section"><div class="rc144-head"><div><h3>Reconhecimentos</h3><p>Valorize quem caminha com você.</p></div><button type="button" class="rc144-more" data-see-all="helpers">Ver todas ›</button></div>
   <div class="rc144-recog">${rc144Img('')}<div><strong>Ajuda incrível</strong><p>A BERTH.A registrou: essa ajuda fez tudo mais leve.</p></div><span class="rc144-date">12 abr. 2024</span><div class="rc144-recog-icons">${['','','','',''].map(a=>rc144Img(a)).join('')}</div></div>
   <details class="rc144-config"><summary>Personalizar reconhecimentos</summary><div class="rc144-config-body">${presets.map((r,i)=>`<div class="reward-config-card" data-rec-preset="${i}"><div class="reward-config-head"><span class="reward-config-icon">${escapeHtml(r.icon||'✦')}</span><div><strong>${escapeHtml(r.name||'Reconhecimento')}</strong><small>${escapeHtml(r.message||'')}</small></div><label class="reward-active"><input type="checkbox" data-rp-active ${r.active!==false?'checked':''}>Ativo</label></div><div class="reward-form-grid"><label>Símbolo<input data-rp-icon value="${escapeHtml(r.icon||'✦')}"></label><label>Nome<input data-rp-name value="${escapeHtml(r.name||'')}"></label></div><label>Mensagem<input data-rp-message value="${escapeHtml(r.message||'')}"></label></div>`).join('')}<div class="reward-config-actions"><button id="rc144SaveRecognition">Salvar reconhecimentos</button></div></div></details>
   </section>
 </section>
 </div>`;

 const activate=(pane)=>{document.querySelectorAll('[data-pane]').forEach(b=>b.classList.toggle('active',b.dataset.pane===pane));document.querySelectorAll('[data-rc144-pane]').forEach(p=>p.hidden=p.dataset.rc144Pane!==pane)};
 document.querySelectorAll('[data-pane]').forEach(b=>b.onclick=()=>activate(b.dataset.pane));
 document.querySelectorAll('[data-see-all]').forEach(b=>b.onclick=()=>rc144OpenAll(b.dataset.seeAll,kid?.id));
 document.querySelector('#rc144KidSelect')?.addEventListener('change',e=>{window.berthaHmlStorage.setItem('bertha.rewards.selected.kid',e.target.value);renderRewardsRC144();activate('kids')});
 document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{if(!kid)return;const all=loadKidsRewardThemes();all[kid.id]=b.dataset.theme;saveKidsRewardThemes(all);document.querySelectorAll('[data-theme]').forEach(x=>x.classList.toggle('active',x===b))});
 let chosenArt='';document.querySelectorAll('[data-art]').forEach(b=>b.onclick=()=>{chosenArt=b.dataset.art;document.querySelectorAll('[data-art]').forEach(x=>x.classList.toggle('active',x===b));const hero=document.querySelector('.hero-art');if(hero)hero.src=RC144_REWARD_ASSET+chosenArt});
 document.querySelector('#rc144NewReward')?.addEventListener('click',()=>{document.querySelector('#rc144RewardName').value='';document.querySelector('#rc144RewardPoints').value=50;document.querySelector('#rc144RewardType').value='medal';document.querySelector('#rc144RewardCriterion').value='points';document.querySelector('#rc144RewardActive').checked=true;document.querySelector('#rc144EditorTitle').textContent='Nova premiação';document.querySelector('#rc144RewardName').focus()});
 document.querySelector('#rc144SaveKidReward')?.addEventListener('click',e=>{if(!kid)return;const name=document.querySelector('#rc144RewardName').value.trim();if(!name)return document.querySelector('#rc144RewardName').focus();const all=loadKidsRewards(),raw=all[kid.id]||{},key='custom_'+Date.now();raw[key]={name,points:Math.max(1,+document.querySelector('#rc144RewardPoints').value||1),type:document.querySelector('#rc144RewardType').value,criterion:document.querySelector('#rc144RewardCriterion').value,active:document.querySelector('#rc144RewardActive').checked,art:chosenArt,recurrence:'season'};all[kid.id]=raw;saveKidsRewards(all);e.currentTarget.textContent='Salvo';setTimeout(()=>{renderRewardsRC144();activate('kids')},500)});
 document.querySelector('#rc144SaveOwner')?.addEventListener('click',e=>{const current=loadOwnerRewards(),vals=[...document.querySelectorAll('[data-owner-reward]')].map((row,i)=>({...current[i],name:row.querySelector('[data-or-name]').value.trim()||current[i].name,icon:row.querySelector('[data-or-icon]').value.trim()||current[i].icon||'✦',criterion:row.querySelector('[data-or-criterion]').value,value:Math.max(1,+row.querySelector('[data-or-value]').value||1),recurrence:row.querySelector('[data-or-rec]').value,visual:row.querySelector('[data-or-visual]').value.trim(),description:row.querySelector('[data-or-desc]').value.trim(),active:row.querySelector('[data-or-active]').checked}));saveOwnerRewards(vals);e.currentTarget.textContent='Salvo';setTimeout(()=>e.currentTarget.textContent='Salvar conquistas',900)});
 document.querySelector('#rc144SaveRecognition')?.addEventListener('click',e=>{const base=loadRecognitionPresets(),vals=[...document.querySelectorAll('[data-rec-preset]')].map((row,i)=>({...base[i],icon:row.querySelector('[data-rp-icon]').value.trim()||base[i].icon||'✦',name:row.querySelector('[data-rp-name]').value.trim()||base[i].name,message:row.querySelector('[data-rp-message]').value.trim(),active:row.querySelector('[data-rp-active]').checked}));saveRecognitionPresets(vals);e.currentTarget.textContent='Salvo';setTimeout(()=>e.currentTarget.textContent='Salvar reconhecimentos',900)});
}

renderUniversalRewards=renderRewardsRC144;
renderKidsRewards=renderRewardsRC144;
(function(){const refresh=()=>{if((location.hash||'').replace('#','')==='premiacoes')try{renderRewardsRC144()}catch(e){console.error('RC144 rewards',e)}};requestAnimationFrame(()=>requestAnimationFrame(refresh));setTimeout(refresh,100);setTimeout(refresh,360)})();


