/* ==============================================================
   RC147 — Premiações fechadas: Owner + Kids + Helper
   ============================================================== */
const R147_ASSET='';
const R147_KIDS_GAME='bertha.kids.game.v2';
const R147_RECOG_TARGET='bertha.recognition.target.v1';
const R147_RECOG_PRESETS='bertha.recognition.presets.v3';

function r147img(name, cls=''){return `<img class="r147-img ${cls}" src="${R147_ASSET}${name}.svg" alt="">`}
function r147jget(k,f){try{const v=JSON.parse(window.berthaHmlStorage.getItem(k)||'null');return v??f}catch{return f}}
function r147jset(k,v){window.berthaHmlStorage.setItem(k,JSON.stringify(v))}
function r147esc(v){return escapeHtml(String(v??''))}
function r147themeDefs(){return {
 mist:{name:'Azul Neblina',grad:'linear-gradient(135deg,#f1eaf4,#dcebf7)',pets:['mist_cat','mist_rabbit','forest_wolf','space_alien','solar_phoenix']},
 ocean:{name:'Oceano',grad:'linear-gradient(135deg,#dff3f8,#c7e5f2)',pets:['ocean_fish','ocean_shark','coral_seahorse','coral_axolotl','mist_cat']},
 space:{name:'Espaço',grad:'linear-gradient(135deg,#dcd8ef,#c8d9f3)',pets:['space_alien','space_astronaut','mist_rabbit','forest_wolf','solar_phoenix']},
 forest:{name:'Floresta',grad:'linear-gradient(135deg,#e3f0e6,#cee0d2)',pets:['forest_wolf','forest_tiger','mist_cat','solar_lion','mist_rabbit']},
 solar:{name:'Solar',grad:'linear-gradient(135deg,#fff1ca,#f4d6a4)',pets:['solar_lion','solar_phoenix','forest_tiger','ocean_fish','space_alien']},
 coral:{name:'Coral',grad:'linear-gradient(135deg,#fae1e1,#f3cedb)',pets:['coral_axolotl','coral_seahorse','ocean_fish','mist_rabbit','space_alien']}
}}
function r147petName(asset){
 return ({mist_cat:'Gato Neblina',mist_rabbit:'Coelho de Nuvem',ocean_fish:'Peixe Azul',ocean_shark:'Tubarão',space_alien:'ET',space_astronaut:'Astronauta',forest_wolf:'Lobo',forest_tiger:'Tigre',solar_lion:'Leão Solar',solar_phoenix:'Fênix',coral_axolotl:'Axolote',coral_seahorse:'Cavalo-marinho'})[asset]||'Companheiro'
}
function r147KidsConfig(mid){
 const all=r147jget(R147_KIDS_GAME,{});
 const raw=all[mid]||{};
 return {
   pointsPerStep:Math.max(1,+raw.pointsPerStep||20),
   medalsPerAccessory:Math.max(1,+raw.medalsPerAccessory||3),
   accessoriesPerPet:Math.max(1,+raw.accessoriesPerPet||5),
   capsuleCount:Math.max(1,Math.min(8,+raw.capsuleCount||5)),
   themes:Array.isArray(raw.themes)&&raw.themes.length?raw.themes:['ocean','space','forest','solar','coral','mist'],
   accessoryNames:Array.isArray(raw.accessoryNames)&&raw.accessoryNames.length?raw.accessoryNames:['Boné','Coleira','Óculos','Mochila','Medalhão'],
   colorOptions:Array.isArray(raw.colorOptions)&&raw.colorOptions.length?raw.colorOptions:['Azul','Verde','Coral','Lilás','Dourado']
 }
}
function r147SaveKidsConfig(mid,cfg){const all=r147jget(R147_KIDS_GAME,{});all[mid]=cfg;r147jset(R147_KIDS_GAME,all)}
function r147KidsState(mid){
 const cfg=r147KidsConfig(mid),p=loadKidsProgress()[mid]||{lifetime:0,season:0,awards:[],log:[]};
 const units=Math.floor((+p.lifetime||0)/cfg.pointsPerStep);
 const pre=6, perPet=pre+cfg.medalsPerAccessory*cfg.accessoriesPerPet;
 let cycle=Math.floor(units/perPet), inCycle=units%perPet;
 if(cycle>=cfg.capsuleCount){cycle=cfg.capsuleCount-1;inCycle=perPet}
 const themeKey=cfg.themes[cycle%cfg.themes.length]||'mist',theme=r147themeDefs()[themeKey]||r147themeDefs().mist;
 const petAsset=theme.pets[cycle%theme.pets.length];
 const petRevealed=inCycle>=pre;
 const after=Math.max(0,inCycle-pre);
 const accessories=Math.min(cfg.accessoriesPerPet,Math.floor(after/cfg.medalsPerAccessory));
 const accessoryMedals=after%cfg.medalsPerAccessory;
 let bigStep=Math.min(5,inCycle);
 const bigNames=['Bronze','Prata','Ouro','Troféu','Super Troféu','Cápsula'];
 return {cfg,p,units,pre,perPet,cycle,inCycle,themeKey,theme,petAsset,petRevealed,accessories,accessoryMedals,bigStep,bigNames,complete:(+p.lifetime||0)>=cfg.capsuleCount*perPet*cfg.pointsPerStep}
}
function r147CoreAwardState(mid){
 const s=r147KidsState(mid), awards=[];
 for(let c=0;c<s.cfg.capsuleCount;c++){
   const base=c*s.perPet;
   const themeKey=s.cfg.themes[c%s.cfg.themes.length]||'mist';
   const theme=r147themeDefs()[themeKey]||r147themeDefs().mist;
   const petAsset=theme.pets[c%theme.pets.length];
   [['bronze',1,'Medalha de Bronze'],['silver',2,'Medalha de Prata'],['gold',3,'Medalha de Ouro'],['trophy',4,'Troféu'],['super',5,'Super Troféu'],['capsule',6,'Cápsula aberta']].forEach(([type,u,name])=>{
     if(s.units>=base+u)awards.push({key:`r147:${c}:${type}`,type,name,cycle:c,theme:themeKey,at:Date.now()})
   });
   if(s.units>=base+6)awards.push({key:`r147:${c}:pet`,type:'pet',name:r147petName(petAsset),asset:petAsset,cycle:c,theme:themeKey,at:Date.now()});
   for(let a=1;a<=s.cfg.accessoriesPerPet;a++){
     const need=base+6+a*s.cfg.medalsPerAccessory;
     if(s.units>=need)awards.push({key:`r147:${c}:acc:${a}`,type:'accessory',name:s.cfg.accessoryNames[a-1]||`Acessório ${a}`,cycle:c,theme:themeKey,at:Date.now()})
   }
 }
 return awards
}
const _r147AwardKidsPoints=awardKidsPoints;
awardKidsPoints=function(memberId,points,title){
 _r147AwardKidsPoints(memberId,points,title);
 const all=loadKidsProgress(),k=all[memberId]||{};
 const legacy=Array.isArray(k.awards)?k.awards.filter(a=>!String(a.key||'').startsWith('r147:')):[];
 k.awards=[...legacy,...r147CoreAwardState(memberId)];
 all[memberId]=k;saveKidsProgress(all);
}

function r147RecognitionDefaults(){return [
 {id:'thanks',asset:'recognition_heart',name:'Obrigada por hoje',message:'Obrigada por deixar o meu dia mais leve.'},
 {id:'flower',asset:'recognition_flower',name:'Uma flor para você',message:'Um carinho para agradecer pela ajuda.'},
 {id:'coffee',asset:'recognition_coffee',name:'Vale café',message:'Um café por minha conta. Obrigada pela ajuda.'},
 {id:'dinner',asset:'recognition_dinner',name:'Vale jantar a dois',message:'Quero retribuir esse cuidado com um jantar a dois.'},
 {id:'family',asset:'recognition_family',name:'Vale almoço em família',message:'Esse reconhecimento vale um almoço gostoso em família.'},
 {id:'gift',asset:'recognition_gift',name:'Um mimo para você',message:'Você fez diferença. Quero te dar um mimo.'},
 {id:'saved',asset:'recognition_saved',name:'Você salvou meu dia',message:'Você salvou meu dia hoje. Obrigada por estar comigo nisso.'},
 {id:'hug',asset:'recognition_hug',name:'Um abraço em forma de obrigada',message:'Receba esse carinho como meu obrigada.'}
]}
function r147RecognitionPresets(){
 const s=r147jget(R147_RECOG_PRESETS,null);
 return Array.isArray(s)&&s.length?s:r147RecognitionDefaults()
}
function r147SaveRecognitionPresets(x){r147jset(R147_RECOG_PRESETS,x)}

function r147Styles(){
 if(document.getElementById('r147styles'))return;
 const s=document.createElement('style');s.id='r147styles';s.textContent=`
 .r147-page{display:grid;gap:14px;padding-bottom:24px}.r147-hero{position:relative;overflow:hidden;padding:22px!important;min-height:174px!important;background:linear-gradient(135deg,#fae7ed 0%,#fff3df 48%,#dfeef9 100%)!important}.r147-hero h2{font-size:29px!important;font-weight:420!important;line-height:1.06!important;letter-spacing:-.025em!important}.r147-hero p{max-width:520px!important}.r147-hero-orbit{position:absolute;right:24px;bottom:24px;width:115px;height:115px;border-radius:50%;border:1px solid rgba(131,112,143,.12)}.r147-hero-orbit:before,.r147-hero-orbit:after{content:'';position:absolute;border-radius:50%;border:1px solid rgba(131,112,143,.1)}.r147-hero-orbit:before{inset:16px}.r147-hero-orbit:after{inset:34px}.r147-hero-orbit i{position:absolute;width:16px;height:16px;border-radius:50%;background:#e8a3ba;left:49px;top:-8px;box-shadow:34px 35px 0 #c7dcf0,-27px 69px 0 #e9c67d}
 .r147-tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;padding:4px;background:rgba(255,253,249,.86);border:1px solid rgba(113,96,130,.08);border-radius:20px}.r147-tabs button{border:0;background:transparent;min-height:44px;border-radius:16px;color:#7b737e;font-size:12px}.r147-tabs button.active{background:#fffdfa;color:#413a45;box-shadow:0 4px 14px rgba(71,57,72,.06)}
 .r147-pane{display:grid;gap:14px}.r147-pane[hidden]{display:none!important}.r147-card{padding:16px;border-radius:25px;background:rgba(255,253,249,.91);border:1px solid rgba(113,96,130,.08);box-shadow:0 10px 24px rgba(74,57,69,.035)}.r147-head{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;margin-bottom:13px}.r147-head h3{margin:0;font-size:20px;font-weight:430;letter-spacing:-.02em}.r147-head p{margin:4px 0 0;color:#8a818b;font-size:11.5px;line-height:1.4}.r147-action{border:1px solid rgba(194,132,160,.16);background:linear-gradient(110deg,#fff4f7,#fff8ef);color:#9a5f79;border-radius:999px;min-height:36px;padding:0 14px;font-size:10.8px;white-space:nowrap}
 .r147-img{width:100%;height:100%;object-fit:contain;display:block}.r147-ach-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.r147-ach{min-height:160px;padding:10px;border-radius:20px;display:grid;justify-items:center;text-align:center;align-content:start;gap:7px;background:linear-gradient(155deg,#fffdfa,#faf7f4);border:1px solid rgba(113,96,130,.07)}.r147-ach .art{width:82px;height:82px}.r147-ach strong{font-size:10.5px;font-weight:430}.r147-ach small{font-size:9.5px;color:#8a818b;line-height:1.25}
 .r147-room{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}.r147-month{min-height:68px;border-radius:17px;padding:9px;display:grid;align-content:center;justify-items:center;text-align:center;border:1px solid rgba(113,96,130,.07);position:relative;overflow:hidden}.r147-month:before{content:'';position:absolute;inset:0;background:var(--g);opacity:.64}.r147-month>*{position:relative}.r147-month strong{font-size:11px;font-weight:430}.r147-month small{font-size:8.5px;color:#706773}.r147-month.current{box-shadow:inset 0 0 0 2px rgba(181,117,148,.24)}
 .r147-kid-head{display:grid;grid-template-columns:66px 1fr auto;gap:12px;align-items:center;padding:13px;border-radius:22px;background:var(--theme);border:1px solid rgba(113,96,130,.08)}.r147-kid-avatar{width:64px;height:64px;border-radius:21px;background:#fffdfa;display:grid;place-items:center}.r147-kid-head h3{margin:0;font-size:19px;font-weight:430}.r147-kid-head p{margin:3px 0 7px;font-size:10.5px;color:#786f7b}.r147-points{padding:8px 10px;border-radius:999px;background:#fff7df;font-size:11px;color:#6d5b35}.r147-bar{height:9px;border-radius:999px;background:rgba(255,255,255,.72);overflow:hidden}.r147-bar span{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#c091e7,#e99bbd,#f2c368)}
 .r147-board{padding:14px;border-radius:24px;background:linear-gradient(145deg,#fffaf6,#f7f8fb);border:1px solid rgba(113,96,130,.08);overflow:hidden}.r147-path{display:grid;grid-template-columns:repeat(6,1fr);gap:9px;position:relative}.r147-path:before{content:'';position:absolute;left:8%;right:8%;top:34px;height:4px;background:#eee8ee;border-radius:999px}.r147-node{position:relative;z-index:1;display:grid;justify-items:center;text-align:center;gap:6px}.r147-node .dot{width:68px;height:68px;border-radius:22px;background:#fff;display:grid;place-items:center;border:1px solid rgba(113,96,130,.08);opacity:.48;filter:grayscale(.25)}.r147-node.done .dot{opacity:1;filter:none;box-shadow:0 6px 16px rgba(76,62,79,.07)}.r147-node.current .dot{opacity:1;filter:none;box-shadow:0 0 0 3px rgba(207,142,173,.13),0 8px 20px rgba(76,62,79,.08)}.r147-node strong{font-size:9.2px;font-weight:430}.r147-node small{font-size:8.4px;color:#8c838d}.r147-pet-stage{margin-top:14px;display:grid;grid-template-columns:125px 1fr;gap:13px;align-items:center;padding:13px;border-radius:20px;background:var(--theme);border:1px solid rgba(113,96,130,.07)}.r147-pet-stage .pet{width:120px;height:120px;border-radius:24px;background:#fffdfa;padding:6px}.r147-pet-stage h4{margin:0;font-size:16px;font-weight:430}.r147-pet-stage p{margin:4px 0 10px;font-size:10.5px;color:#776e79;line-height:1.4}.r147-accessories{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.r147-accessory{min-height:63px;border-radius:15px;background:rgba(255,255,255,.78);border:1px solid rgba(113,96,130,.07);padding:6px;display:grid;justify-items:center;text-align:center;opacity:.43}.r147-accessory.done{opacity:1}.r147-accessory img{width:38px;height:38px}.r147-accessory small{font-size:7.8px;color:#6f6871}
 .r147-theme-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.r147-theme{min-height:65px;border:1px solid rgba(113,96,130,.08);border-radius:18px;padding:9px;text-align:left;position:relative;background:var(--theme)}.r147-theme strong{font-size:11px;font-weight:430}.r147-theme small{display:block;margin-top:3px;font-size:9px;color:#756d78}.r147-theme.active:after{content:'✓';position:absolute;right:9px;top:9px;width:20px;height:20px;border-radius:50%;background:#c888a7;color:#fff;display:grid;place-items:center;font-size:11px}
 .r147-config{display:grid;gap:10px}.r147-config-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.r147-config label{display:grid;gap:5px;font-size:10.5px;color:#817984}.r147-config input,.r147-config select,.r147-config textarea{min-height:42px;border-radius:13px;border:1px solid rgba(113,96,130,.13);background:#fff;padding:9px 10px;font-size:16px;color:#49434d}
 .r147-helper-context{display:grid;grid-template-columns:54px 1fr;gap:11px;align-items:center;padding:12px;border-radius:20px;background:linear-gradient(135deg,#f8e9ef,#edf4f8);margin-bottom:12px}.r147-helper-context .sat-avatar{width:54px;height:54px}.r147-rec-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.r147-rec{border:1px solid rgba(113,96,130,.08);border-radius:18px;background:#fffdfa;padding:10px;display:grid;grid-template-columns:48px 1fr;gap:8px;align-items:center;text-align:left}.r147-rec img{width:48px;height:48px}.r147-rec strong{font-size:10.5px;font-weight:430}.r147-rec small{display:block;font-size:9px;color:#8a818b;margin-top:2px;line-height:1.25}
 .r147-dialog{max-width:min(720px,calc(100vw - 22px));width:100%;border:0;padding:0;background:transparent}.r147-dialog::backdrop{background:rgba(58,48,62,.28);backdrop-filter:blur(5px)}.r147-dialog-card{max-height:84dvh;overflow:auto;padding:18px;border-radius:26px;background:#fffaf5;border:1px solid rgba(113,96,130,.08);box-shadow:0 25px 70px rgba(57,43,61,.18)}.r147-dialog-head{display:flex;justify-content:space-between;gap:10px}.r147-dialog-head h3{margin:0;font-size:21px;font-weight:430}.r147-close{width:42px;height:42px;border-radius:50%;border:1px solid rgba(113,96,130,.09);background:#fff;color:#6d6570;font-size:22px}.r147-collection{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin-top:13px}.r147-col-item{padding:10px;border-radius:18px;background:#fff;border:1px solid rgba(113,96,130,.07);display:grid;justify-items:center;text-align:center;gap:6px}.r147-col-item img{width:72px;height:72px}.r147-col-item strong{font-size:10.5px;font-weight:430}.r147-col-item small{font-size:9px;color:#8b828c}
 .sat-event{grid-template-columns:24px minmax(0,1fr) auto!important}.sat-event .r147-rec-now{border:1px solid rgba(190,132,158,.14);background:linear-gradient(110deg,#fff2f6,#fff7ed);color:#9a5b78;border-radius:999px;min-height:34px;padding:0 11px;font-size:10px;white-space:nowrap}
 @media(max-width:560px){.r147-ach-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.r147-room{grid-template-columns:repeat(4,minmax(0,1fr))}.r147-path{grid-template-columns:repeat(3,1fr)}.r147-pet-stage{grid-template-columns:1fr}.r147-pet-stage .pet{justify-self:center}.r147-theme-grid,.r147-rec-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.r147-config-grid{grid-template-columns:1fr}.r147-kid-head{grid-template-columns:58px 1fr}.r147-points{grid-column:2;justify-self:start}.r147-collection{grid-template-columns:repeat(2,minmax(0,1fr))}}
 `;document.head.appendChild(s)
}
function r147Dialog(title,html){
 r147Styles();const d=document.createElement('dialog');d.className='r147-dialog';d.innerHTML=`<div class="r147-dialog-card"><div class="r147-dialog-head"><div><div class="eyebrow">BERTH.A</div><h3>${r147esc(title)}</h3></div><button type="button" class="r147-close">×</button></div>${html}</div>`;document.body.appendChild(d);d.querySelector('.r147-close').onclick=()=>d.close();d.onclick=e=>{if(e.target===d)d.close()};d.onclose=()=>d.remove();d.showModal();return d
}
function r147OwnerCollection(){
 const items=[
 ['medal_bronze','Constância','7 dias'],['medal_silver','Ritmo','ciclo mantido'],['medal_gold','Marco','meta alcançada'],
 ['trophy','Ciclo completo','100%'],['super_trophy','Super marco','sequência especial'],['accessory_badge','Autocuidado','presença'],
 ['capsule','Projeto concluído','entrega importante'],['recognition_flower','Equilíbrio','semana alinhada'],['recognition_heart','Cuidado consigo','ritual mantido'],
 ['medal_gold','Evolução','novo patamar'],['trophy','Foco','30 dias'],['super_trophy','Conquista especial','marco único']
 ];
 r147Dialog('Sala de Troféus',`<div class="r147-collection">${items.map((x,i)=>`<div class="r147-col-item" style="background:${['#fff2f4','#edf4f9','#fff4dd','#eef5ef'][i%4]}">${r147img(x[0])}<strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}</div>`)
}
function r147KidsCollection(mid){
 const st=r147KidsState(mid),aw=r147CoreAwardState(mid);
 const html=aw.length?aw.map(a=>{let asset=a.asset||({bronze:'medal_bronze',silver:'medal_silver',gold:'medal_gold',trophy:'trophy',super:'super_trophy',capsule:'capsule',accessory:['accessory_cap','accessory_collar','accessory_glasses','accessory_backpack','accessory_badge'][Math.max(0,(+String(a.key).split(':').pop()||1)-1)]})[a.type]||'medal_bronze';return `<div class="r147-col-item">${r147img(asset)}<strong>${r147esc(a.name)}</strong><small>Ciclo ${a.cycle+1}</small></div>`}).join(''):`<div class="sat-empty" style="grid-column:1/-1">A coleção começa na primeira medalha.</div>`;
 r147Dialog('Coleção Kids',`<div class="r147-collection">${html}</div>`)
}

function r147OpenRecognition(memberId,eventId=''){
 r147Styles();const m=satelliteMember(memberId);if(!m)return;
 const events=loadSatelliteOwnerEvents(),ev=events.find(x=>String(x.id)===String(eventId))||events.find(x=>String(x.memberId)===String(memberId)&&x.type==='completed');
 const presets=r147RecognitionPresets().filter(x=>x.active!==false);let chosen=0;
 const d=r147Dialog(`Reconhecer ${m.name}`,`<div class="r147-helper-context"><span class="sat-avatar">${satelliteAvatarIcon(m.avatarKey||'family')}</span><div><strong>${r147esc(m.name)}</strong><small>${ev?`concluiu “${r147esc(ev.taskName)}”`:'Reconhecimento da sua rede'}</small></div></div><div class="r147-rec-grid">${presets.map((r,i)=>`<button type="button" class="r147-rec ${i===0?'active':''}" data-r147-choice="${i}">${r147img(r.asset||'recognition_heart')}<span><strong>${r147esc(r.name)}</strong><small>${r147esc(r.message)}</small></span></button>`).join('')}</div><div class="r147-config" style="margin-top:12px"><label>Mensagem<input id="r147RecMessage" value="${r147esc(presets[0]?.message||'')}"></label><button type="button" class="primary" id="r147SendRecognition">Enviar reconhecimento</button></div>`);
 const msg=d.querySelector('#r147RecMessage');
 d.querySelectorAll('[data-r147-choice]').forEach(b=>b.onclick=()=>{chosen=+b.dataset.r147Choice;d.querySelectorAll('[data-r147-choice]').forEach(x=>x.classList.toggle('active',x===b));msg.value=presets[chosen]?.message||''});
 d.querySelector('#r147SendRecognition').onclick=()=>{const r=presets[chosen];if(!r)return;const hist=loadRecognitions();hist.unshift({id:satId(),memberId:m.id,memberName:m.name,asset:r.asset,name:r.name,message:msg.value.trim()||r.message,taskId:ev?.taskId||null,taskName:ev?.taskName||'',at:Date.now()});saveRecognitions(hist);if(ev){const all=loadSatelliteOwnerEvents();const hit=all.find(x=>String(x.id)===String(ev.id));if(hit){hit.read=true;hit.recognizedAt=Date.now();saveSatelliteOwnerEvents(all)}}d.close();if((location.hash||'').includes('premiacoes'))renderRewardsRC147('helpers')};
}
openRecognitionModal=r147OpenRecognition;

function renderRewardsRC147(forceTab=''){
 r147Styles();ensureSatelliteStyles();ensureSatelliteIdentityV4();
 const data=loadSatellites(),kids=(data.members||[]).filter(m=>m.status!=='removed'&&m.role==='kids'),helpers=(data.members||[]).filter(m=>m.status!=='removed'&&m.role!=='kids');
 const target=window.berthaHmlStorage.getItem(R147_RECOG_TARGET)||'',targetMember=satelliteMember(target);
 let kidId=window.berthaHmlStorage.getItem('bertha.rewards.selected.kid')||kids[0]?.id||'',kid=kids.find(x=>String(x.id)===String(kidId))||kids[0];
 if(kid){kidId=kid.id;window.berthaHmlStorage.setItem('bertha.rewards.selected.kid',kid.id)}
 const st=kid?r147KidsState(kid.id):null,month=new Date().getMonth(),year=new Date().getFullYear();
 const monthGrad=['linear-gradient(135deg,#f6dce6,#e8eef7)','linear-gradient(135deg,#e0edf8,#e7e0f2)','linear-gradient(135deg,#e7f2e9,#f4e5ca)','linear-gradient(135deg,#f5ddd4,#e8dcf1)','linear-gradient(135deg,#e3dff4,#dcecf6)','linear-gradient(135deg,#e1f1e8,#f4e7c8)','linear-gradient(135deg,#f5e2b8,#efd5d5)','linear-gradient(135deg,#e0edf8,#d9e9ec)','linear-gradient(135deg,#f0dce4,#f6e7c7)','linear-gradient(135deg,#e2f0e8,#e5def3)','linear-gradient(135deg,#e5dff1,#dcecf8)','linear-gradient(135deg,#f3dce3,#f3e7d1)'];
 const ownerTiles=[['medal_gold','Constância','Sequência mantida'],['trophy','Rotina em dia','Ciclo concluído'],['super_trophy','Foco','Marco especial'],['accessory_badge','Escolhas conscientes','Evolução registrada']];
 const recs=r147RecognitionPresets(),activeHelper=targetMember&&targetMember.role!=='kids'?targetMember:helpers[0];

 app.innerHTML=`<div class="r147-page">
 <section class="sat-hero sat-ideal-hero r147-hero"><div class="r148-build">HML · RC169</div><div class="sat-hero-copy"><div class="eyebrow">PREMIAÇÕES</div><h2>Você desempenha.<br>A BERTH.A reconhece.</h2><p>Conquistas para você. Um universo de progressão para Kids. Reconhecimento para quem caminha junto.</p></div><div class="r147-hero-orbit"><i></i></div></section>
 <div class="r147-tabs"><button data-r147tab="owner">Owner</button><button data-r147tab="kids">Kids</button><button data-r147tab="helpers">Reconhecimentos</button></div>
 <section class="r147-pane" data-r147pane="owner">
   <section class="r147-card"><div class="r147-head"><div><h3>Minhas conquistas</h3><p>Marcos pessoais, sem pontos e sem linguagem infantil.</p></div><button class="r147-action" id="r147OwnerRoom">Sala de Troféus ›</button></div><div class="r147-ach-grid">${ownerTiles.map(x=>`<div class="r147-ach">${`<div class="art">${r147img(x[0])}</div>`}<strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}</div></section>
   <section class="r147-card"><div class="r147-head"><div><h3>Sala de Troféus · ${year}</h3><p>Cumulativa. Cada ciclo mensal ganha uma identidade própria e permanece no histórico.</p></div></div><div class="r147-room">${Array.from({length:12},(_,i)=>`<div class="r147-month ${i===month?'current':''}" style="--g:${monthGrad[i]}"><strong>${['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'][i]}</strong><small>${i<month?'coleção':i===month?'em curso':'a descobrir'}</small></div>`).join('')}</div></section>
   <section class="r147-card"><details><summary style="cursor:pointer;font-weight:430">Personalizar conquistas do Owner</summary><div class="r147-config" style="margin-top:12px">${loadOwnerRewards().map((r,i)=>`<div class="reward-config-card" data-r147-owner="${i}"><div class="reward-config-head"><div><strong>${r147esc(r.name)}</strong><small>${r147esc(r.description||'')}</small></div><label class="reward-active"><input type="checkbox" data-active ${r.active!==false?'checked':''}>Ativa</label></div><div class="r147-config-grid"><label>Nome<input data-name value="${r147esc(r.name)}"></label><label>Critério<select data-criterion><option value="progress100" ${r.criterion==='progress100'?'selected':''}>Progresso em 100%</option><option value="goal" ${r.criterion==='goal'?'selected':''}>Meta concluída</option><option value="streak" ${r.criterion==='streak'?'selected':''}>Sequência</option><option value="cycle" ${r.criterion==='cycle'?'selected':''}>Ciclo concluído</option></select></label><label>Recorrência<select data-rec><option value="once" ${r.recurrence==='once'?'selected':''}>Única</option><option value="each" ${r.recurrence==='each'?'selected':''}>Cada vez</option><option value="weekly" ${r.recurrence==='weekly'?'selected':''}>Semanal</option><option value="monthly" ${r.recurrence==='monthly'?'selected':''}>Mensal</option></select></label></div></div>`).join('')}<button class="primary" id="r147SaveOwner">Salvar conquistas</button></div></details></section>
 </section>
 <section class="r147-pane" data-r147pane="kids">
 ${kid?`<section class="r147-card"><div class="r147-head"><div><h3>Universo Kids</h3><p>O Owner controla a lógica; a criança vive a trilha e personaliza apenas o que desbloquear.</p></div><select id="r147KidSel" style="min-height:36px;border-radius:999px;border:1px solid rgba(113,96,130,.1);background:#fff;padding:0 12px">${kids.map(k=>`<option value="${k.id}" ${String(k.id)===String(kid.id)?'selected':''}>${r147esc(k.name)}</option>`).join('')}</select></div>
 <div class="r147-kid-head" style="--theme:${st.theme.grad}"><span class="r147-kid-avatar">${satelliteAvatarIcon(kid.avatarKey||'son')}</span><div><h3>${r147esc(kid.name)}</h3><p>Ciclo ${st.cycle+1} · ${st.theme.name} · ${st.petRevealed?r147petName(st.petAsset):'cápsula ainda fechada'}</p><div class="r147-bar"><span style="width:${Math.min(100,(st.inCycle/st.perPet)*100)}%"></span></div></div><span class="r147-points">★ ${+st.p.lifetime||0} pts</span></div>
 <div class="r147-board"><div class="r147-head"><div><h3 style="font-size:16px">Trilha do ciclo</h3><p>Bronze → Prata → Ouro → Troféu → Super Troféu → Cápsula.</p></div><button class="r147-action" id="r147KidCollection">Coleção ›</button></div><div class="r147-path">${[
 ['medal_bronze','Bronze',1],['medal_silver','Prata',2],['medal_gold','Ouro',3],['trophy','Troféu',4],['super_trophy','Super Troféu',5],['capsule','Cápsula',6]
 ].map(x=>`<div class="r147-node ${st.inCycle>=x[2]?'done':''} ${st.inCycle+1===x[2]?'current':''}"><span class="dot">${r147img(x[0])}</span><strong>${x[1]}</strong><small>${x[2]*st.cfg.pointsPerStep} pts</small></div>`).join('')}</div>
 <div class="r147-pet-stage" style="--theme:${st.theme.grad}"><div class="pet">${st.petRevealed?r147img(st.petAsset):r147img('capsule')}</div><div><h4>${st.petRevealed?r147petName(st.petAsset):'A surpresa ainda está na cápsula'}</h4><p>${st.petRevealed?`A cada ${st.cfg.medalsPerAccessory} medalhas, um novo acessório é liberado. Complete ${st.cfg.accessoriesPerPet} para avançar ao próximo grande ciclo.`:'Chegue ao Super Troféu e complete o próximo marco para abrir a cápsula.'}</p><div class="r147-accessories">${st.cfg.accessoryNames.slice(0,st.cfg.accessoriesPerPet).map((n,i)=>`<div class="r147-accessory ${i<st.accessories?'done':''}">${r147img(['accessory_cap','accessory_collar','accessory_glasses','accessory_backpack','accessory_badge'][i%5])}<small>${r147esc(n)}</small></div>`).join('')}</div></div></div></div></section>
 <section class="r147-card"><div class="r147-head"><div><h3>Temas visuais</h3><p>O tema pode voltar em outro ciclo sem repetir a surpresa: cada universo possui vários pets.</p></div></div><div class="r147-theme-grid">${Object.entries(r147themeDefs()).map(([key,t])=>`<button type="button" class="r147-theme ${st.themeKey===key?'active':''}" data-r147theme="${key}" style="--theme:${t.grad}"><strong>${t.name}</strong><small>${t.pets.slice(0,3).map(r147petName).join(' · ')}</small></button>`).join('')}</div></section>
 <section class="r147-card"><div class="r147-head"><div><h3>Configuração do Owner</h3><p>Uma tarefa mais valiosa pode atravessar vários marcos de uma vez; nenhum ponto é perdido.</p></div></div><div class="r147-config"><div class="r147-config-grid"><label>Pontos por marco<input id="r147PointsStep" type="number" min="1" value="${st.cfg.pointsPerStep}"></label><label>Medalhas por acessório<input id="r147MedalsAcc" type="number" min="1" value="${st.cfg.medalsPerAccessory}"></label><label>Acessórios por pet<input id="r147AccPet" type="number" min="1" max="8" value="${st.cfg.accessoriesPerPet}"></label><label>Número de cápsulas<input id="r147Capsules" type="number" min="1" max="8" value="${st.cfg.capsuleCount}"></label><label>Ordem dos temas<input id="r147ThemeOrder" value="${r147esc(st.cfg.themes.join(', '))}"></label><label>Cores disponíveis<input id="r147Colors" value="${r147esc(st.cfg.colorOptions.join(', '))}"></label></div><label>Nomes dos acessórios<input id="r147AccNames" value="${r147esc(st.cfg.accessoryNames.join(', '))}"></label><button class="primary" id="r147SaveKidCfg">Salvar configuração Kids</button></div></section>`:`<section class="r147-card"><div class="sat-empty">Cadastre um satélite como Kids para configurar a gamificação.</div></section>`}
 </section>
 <section class="r147-pane" data-r147pane="helpers">
   <section class="r147-card"><div class="r147-head"><div><h3>Reconhecimentos</h3><p>Sem pontos e sem ranking. Um gesto imediato para quem ajudou.</p></div></div>
   ${activeHelper?`<div class="r147-helper-context"><span class="sat-avatar">${satelliteAvatarIcon(activeHelper.avatarKey||'family')}</span><div><strong>${r147esc(activeHelper.name)}</strong><small>${targetMember?'Aberto diretamente da atividade concluída.':'Selecione um reconhecimento e envie.'}</small></div></div><div class="r147-rec-grid">${recs.filter(x=>x.active!==false).map((r,i)=>`<button type="button" class="r147-rec" data-r147-rec="${i}">${r147img(r.asset)}<span><strong>${r147esc(r.name)}</strong><small>${r147esc(r.message)}</small></span></button>`).join('')}</div>`:`<div class="sat-empty">Adicione um satélite adulto para usar Reconhecimentos.</div>`}
   </section>
   <section class="r147-card"><details><summary style="cursor:pointer;font-weight:430">Personalizar reconhecimentos</summary><div class="r147-config" style="margin-top:12px">${recs.map((r,i)=>`<div class="reward-config-card" data-r147-preset="${i}"><div class="reward-config-head">${r147img(r.asset)}<div><strong>${r147esc(r.name)}</strong><small>${r147esc(r.message)}</small></div><label class="reward-active"><input type="checkbox" data-active ${r.active!==false?'checked':''}>Ativo</label></div><div class="r147-config-grid"><label>Nome<input data-name value="${r147esc(r.name)}"></label><label style="grid-column:span 2">Mensagem padrão<input data-msg value="${r147esc(r.message)}"></label></div></div>`).join('')}<button class="primary" id="r147SaveRecPresets">Salvar reconhecimentos</button></div></details></section>
 </section></div>`;

 const activate=(name)=>{document.querySelectorAll('[data-r147tab]').forEach(b=>b.classList.toggle('active',b.dataset.r147tab===name));document.querySelectorAll('[data-r147pane]').forEach(p=>p.hidden=p.dataset.r147pane!==name)}
 const initial=forceTab||((targetMember&&targetMember.role!=='kids')?'helpers':'owner');activate(initial);
 document.querySelectorAll('[data-r147tab]').forEach(b=>b.onclick=()=>activate(b.dataset.r147tab));
 document.querySelector('#r147OwnerRoom')?.addEventListener('click',r147OwnerCollection);
 document.querySelector('#r147KidCollection')?.addEventListener('click',()=>kid&&r147KidsCollection(kid.id));
 document.querySelector('#r147KidSel')?.addEventListener('change',e=>{window.berthaHmlStorage.setItem('bertha.rewards.selected.kid',e.target.value);renderRewardsRC147('kids')});
 document.querySelectorAll('[data-r147theme]').forEach(b=>b.onclick=()=>{if(!kid)return;const cfg=r147KidsConfig(kid.id),order=[b.dataset.r147theme,...cfg.themes.filter(x=>x!==b.dataset.r147theme)];cfg.themes=order;r147SaveKidsConfig(kid.id,cfg);renderRewardsRC147('kids')});
 document.querySelector('#r147SaveKidCfg')?.addEventListener('click',e=>{if(!kid)return;const cfg=r147KidsConfig(kid.id);cfg.pointsPerStep=Math.max(1,+document.querySelector('#r147PointsStep').value||20);cfg.medalsPerAccessory=Math.max(1,+document.querySelector('#r147MedalsAcc').value||3);cfg.accessoriesPerPet=Math.max(1,Math.min(8,+document.querySelector('#r147AccPet').value||5));cfg.capsuleCount=Math.max(1,Math.min(8,+document.querySelector('#r147Capsules').value||5));cfg.themes=document.querySelector('#r147ThemeOrder').value.split(',').map(x=>x.trim()).filter(x=>r147themeDefs()[x]);if(!cfg.themes.length)cfg.themes=['ocean','space','forest','solar','coral','mist'];cfg.colorOptions=document.querySelector('#r147Colors').value.split(',').map(x=>x.trim()).filter(Boolean);cfg.accessoryNames=document.querySelector('#r147AccNames').value.split(',').map(x=>x.trim()).filter(Boolean);r147SaveKidsConfig(kid.id,cfg);e.currentTarget.textContent='Salvo';setTimeout(()=>renderRewardsRC147('kids'),500)});
 document.querySelectorAll('[data-r147-rec]').forEach(b=>b.onclick=()=>activeHelper&&r147OpenRecognition(activeHelper.id));
 document.querySelector('#r147SaveRecPresets')?.addEventListener('click',e=>{const base=r147RecognitionPresets();const vals=[...document.querySelectorAll('[data-r147-preset]')].map((row,i)=>({...base[i],name:row.querySelector('[data-name]').value.trim()||base[i].name,message:row.querySelector('[data-msg]').value.trim(),active:row.querySelector('[data-active]').checked}));r147SaveRecognitionPresets(vals);e.currentTarget.textContent='Salvo';setTimeout(()=>e.currentTarget.textContent='Salvar reconhecimentos',900)});
 document.querySelector('#r147SaveOwner')?.addEventListener('click',e=>{const current=loadOwnerRewards(),vals=[...document.querySelectorAll('[data-r147-owner]')].map((row,i)=>({...current[i],name:row.querySelector('[data-name]').value.trim()||current[i].name,criterion:row.querySelector('[data-criterion]').value,recurrence:row.querySelector('[data-rec]').value,active:row.querySelector('[data-active]').checked}));saveOwnerRewards(vals);e.currentTarget.textContent='Salvo';setTimeout(()=>e.currentTarget.textContent='Salvar conquistas',900)});
}
renderUniversalRewards=renderRewardsRC147;renderKidsRewards=renderRewardsRC147;

/* Owner recebe a atividade já descrita e, para Helper, tem apenas "Reconhecer agora". */
const _r147RenderSatellites=renderSatellites;
renderSatellites=function(){
 _r147RenderSatellites();r147Styles();
 const events=loadSatelliteOwnerEvents();
 document.querySelectorAll('.sat-event').forEach((row,i)=>{
   const ev=events[i];if(!ev)return;
   const m=satelliteMember(ev.memberId);
   if(!m||m.role==='kids'||row.querySelector('.r147-rec-now'))return;
   const b=document.createElement('button');b.type='button';b.className='r147-rec-now';b.textContent='Reconhecer agora';
   b.onclick=()=>{window.berthaHmlStorage.setItem(R147_RECOG_TARGET,m.id);window.berthaHmlStorage.setItem('bertha.recognition.event',ev.id);location.hash='#premiacoes';setTimeout(()=>renderRewardsRC147('helpers'),20)};
   row.appendChild(b)
 });
};
window.renderSatellites=renderSatellites;

