const R150_OWNER_PALETTE_KEY='bertha.owner.trophy.palette.v1';

function r150OwnerPalettes(){return {
  blush:{name:'Blush',sw:['#f3dce6','#f7e9dc','#e5edf7','#eadff1']},
  mist:{name:'Neblina',sw:['#e2edf7','#e7e1f2','#f1e4eb','#e9eee8']},
  sage:{name:'Sálvia',sw:['#e2eee6','#d9e6dc','#f2ead6','#e8e2ef']},
  peach:{name:'Pêssego',sw:['#f6e0d3','#f2e8d9','#e4edf5','#efdde7']},
  ocean:{name:'Oceano',sw:['#dcecf5','#d4e4ee','#e8e1f2','#e8eee9']},
  plum:{name:'Ameixa',sw:['#eaddea','#e6e0f2','#f1e1e8','#e4edf4']}
}}
function r150OwnerPalette(){
  const k=window.berthaHmlStorage.getItem(R150_OWNER_PALETTE_KEY)||'blush';
  return r150OwnerPalettes()[k]?k:'blush'
}
function r150ApplyOwnerPalette(){
  const pal=r150OwnerPalettes()[r150OwnerPalette()];
  document.querySelectorAll('.r147-month').forEach((m,i)=>{
    const c=pal.sw[i%pal.sw.length],d=pal.sw[(i+1)%pal.sw.length];
    m.style.setProperty('--g',`linear-gradient(135deg,${c},${d})`);
  });
  document.querySelectorAll('.r147-ach').forEach((m,i)=>{
    m.style.background=`linear-gradient(155deg,${pal.sw[i%pal.sw.length]}88,#fffdfa)`;
  });
}
function r150OwnerPaletteControl(){
  const room=[...document.querySelectorAll('.r147-card')].find(x=>x.querySelector('h3')?.textContent?.includes('Sala de Troféus ·'));
  if(!room||room.querySelector('.r150-owner-palette'))return;
  const wrap=document.createElement('div');wrap.className='r150-owner-palette';
  wrap.innerHTML=`<div><strong>Paleta da Sala</strong><small>Você pode mudar as cores sem alterar suas conquistas.</small></div><div class="r150-palette-buttons">${Object.entries(r150OwnerPalettes()).map(([k,p])=>`<button type="button" data-r150-palette="${k}" class="${k===r150OwnerPalette()?'active':''}"><span>${p.sw.map(c=>`<i style="background:${c}"></i>`).join('')}</span><small>${p.name}</small></button>`).join('')}</div>`;
  room.appendChild(wrap);
  wrap.querySelectorAll('[data-r150-palette]').forEach(b=>b.onclick=()=>{
    window.berthaHmlStorage.setItem(R150_OWNER_PALETTE_KEY,b.dataset.r150Palette);
    wrap.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));
    r150ApplyOwnerPalette();
  });
}

r147OwnerCollection=function(){
 const items=[
  ['owner_consistency','Constância','7 dias de presença'],
  ['owner_cycle','Ciclo concluído','rotina, treino ou projeto'],
  ['owner_focus','Foco','30 dias em movimento'],
  ['owner_balance','Equilíbrio','semana alinhada'],
  ['owner_goal','Meta alcançada','objetivo concluído'],
  ['owner_presence','Presença','ritual mantido'],
  ['owner_consistency','Sequência','novo marco'],
  ['owner_cycle','Continuidade','ciclo renovado'],
  ['owner_goal','Projeto entregue','etapa importante'],
  ['owner_balance','Autocuidado','escolha consciente'],
  ['owner_focus','Profundidade','foco sustentado'],
  ['owner_presence','Evolução','histórico pessoal']
 ];
 const pal=r150OwnerPalettes()[r150OwnerPalette()];
 r147Dialog('Sala de Troféus',`<div class="r150-owner-room-intro"><strong>Sua história de progresso</strong><small>Conquistas cumulativas, sem pontos e sem linguagem Kids.</small></div><div class="r147-collection">${items.map((x,i)=>`<div class="r147-col-item r150-owner-col" style="background:linear-gradient(150deg,${pal.sw[i%pal.sw.length]}99,#fff)">${r147img(x[0])}<strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}</div>`)
};

function r150AccessoryData(themeKey){
 const map={
  ocean:[
   ['accessory_cap','Boné marítimo'],['accessory_collar','Coleira-concha'],['accessory_glasses','Óculos de mergulho'],['accessory_backpack','Mochila oceano'],['accessory_badge','Medalhão pérola']
  ],
  space:[
   ['accessory_glasses','Visor espacial'],['accessory_collar','Colar orbital'],['accessory_badge','Insígnia estelar'],['accessory_backpack','Jetpack'],['accessory_cap','Capacete leve']
  ],
  forest:[
   ['accessory_cap','Chapéu da floresta'],['accessory_collar','Coleira de folhas'],['accessory_glasses','Óculos aventura'],['accessory_backpack','Mochila explorador'],['accessory_badge','Medalhão natural']
  ],
  solar:[
   ['accessory_glasses','Óculos solares'],['accessory_collar','Colar dourado'],['accessory_cap','Coroa solar'],['accessory_backpack','Capa de luz'],['accessory_badge','Emblema do sol']
  ],
  coral:[
   ['accessory_cap','Tiara coral'],['accessory_collar','Colar de pérolas'],['accessory_glasses','Óculos coral'],['accessory_backpack','Bolsa-concha'],['accessory_badge','Medalhão marinho']
  ],
  mist:[
   ['accessory_cap','Gorro de nuvem'],['accessory_collar','Pingente lunar'],['accessory_glasses','Óculos neblina'],['accessory_backpack','Mochila celeste'],['accessory_badge','Emblema de estrela']
  ]
 };
 return map[themeKey]||map.mist
}
function r150KidsEnhance(){
 const kidSel=document.querySelector('#r147KidSel');
 if(!kidSel)return;
 const kidId=kidSel.value;
 const st=r147KidsState(kidId);
 const themeCard=[...document.querySelectorAll('.r147-card')].find(x=>x.querySelector('h3')?.textContent==='Temas visuais');
 if(themeCard&&!themeCard.querySelector('.r150-pet-gallery')){
   const g=document.createElement('div');g.className='r150-pet-gallery';
   g.innerHTML=`<div class="r150-pet-gallery-head"><strong>Pets possíveis · ${st.theme.name}</strong><small>O tema pode se repetir sem repetir a surpresa.</small></div><div class="r150-pets">${st.theme.pets.map((p,i)=>`<div class="r150-pet"><div>${r147img(p)}</div><strong>${r147esc(r147petName(p))}</strong><small>${i===st.cycle%st.theme.pets.length?'pet deste ciclo':'pode aparecer em outro ciclo'}</small></div>`).join('')}</div>`;
   themeCard.appendChild(g);
 }
 document.querySelectorAll('.r147-theme').forEach(btn=>{
   if(btn.querySelector('.r150-theme-pets'))return;
   const key=btn.dataset.r147theme,t=r147themeDefs()[key];
   if(!t)return;
   const previews=document.createElement('div');previews.className='r150-theme-pets';
   previews.innerHTML=t.pets.slice(0,4).map(p=>`<span title="${r147esc(r147petName(p))}">${r147img(p)}</span>`).join('');
   btn.appendChild(previews);
 });
 const acc=document.querySelector('.r147-accessories');
 if(acc){
   const list=r150AccessoryData(st.themeKey);
   const colors=st.cfg.colorOptions?.length?st.cfg.colorOptions:['Azul','Verde','Coral','Lilás','Dourado'];
   acc.innerHTML=list.slice(0,st.cfg.accessoriesPerPet).map((x,i)=>`<div class="r147-accessory ${i<st.accessories?'done':''}"><img src="${r147assetSrc(x[0])}" alt=""><small>${r147esc(x[1])}</small>${i<st.accessories?`<select class="r150-acc-color" data-acc="${i}">${colors.map(c=>`<option>${r147esc(c)}</option>`).join('')}</select>`:''}</div>`).join('');
 }
}
function r150OwnerEnhance(){
 const ownerTiles=document.querySelectorAll('[data-r147pane="owner"] .r147-ach .art');
 const assets=['owner_consistency','owner_cycle','owner_focus','owner_balance'];
 ownerTiles.forEach((a,i)=>{if(assets[i])a.innerHTML=r147img(assets[i])});
 r150OwnerPaletteControl();r150ApplyOwnerPalette()
}
function r150EnhanceRewards(){
 r150OwnerEnhance();r150KidsEnhance()
}

