/* ============================================================
   RC152 — biblioteca visual final inicial + ciclo Kids enxuto
   + Satélites: rota direta sem hashchange
   ============================================================ */
const R152_CYCLES='bertha.kids.cycles.v2';
const R152_OWNER_PALETTE='bertha.owner.pin.palette.v2';

function r152Themes(){return {
  mist:{name:'Azul Neblina',capsule:'capsule_mist',pets:['mist_cat_cute','mist_rabbit_cute','mist_fox_cute'],acc:['mist_acc_cap','mist_acc_collar','mist_acc_glasses','mist_acc_backpack','mist_acc_badge','mist_acc_special']},
  ocean:{name:'Oceano',capsule:'capsule_ocean',pets:['ocean_turtle_cute','ocean_shark_cute','ocean_dolphin_cute','ocean_octopus_cute','ocean_whale_cute','ocean_clownfish_cute'],acc:['ocean_acc_cap','ocean_acc_collar','ocean_acc_glasses','ocean_acc_backpack','ocean_acc_badge','ocean_acc_special']},
  space:{name:'Espaço',capsule:'capsule_space',pets:['space_alien_cute','space_robot_cute','space_cat_cute'],acc:['space_acc_cap','space_acc_collar','space_acc_glasses','space_acc_backpack','space_acc_badge','space_acc_special']},
  forest:{name:'Floresta',capsule:'capsule_forest',pets:['forest_wolf_cute','forest_fox_cute','forest_tiger_cute'],acc:['forest_acc_cap','forest_acc_collar','forest_acc_glasses','forest_acc_backpack','forest_acc_badge','forest_acc_special']},
  solar:{name:'Solar',capsule:'capsule_solar',pets:['solar_lion_cute','solar_dragon_cute','solar_phoenix_cute'],acc:['solar_acc_cap','solar_acc_collar','solar_acc_glasses','solar_acc_backpack','solar_acc_badge','solar_acc_special']},
  coral:{name:'Coral',capsule:'capsule_coral',pets:['coral_axolotl_cute','coral_octopus_cute','coral_seahorse_cute'],acc:['coral_acc_cap','coral_acc_collar','coral_acc_glasses','coral_acc_backpack','coral_acc_badge','coral_acc_special']}
}}
function r152PetLabel(x){
 const m={
 mist_cat_cute:'Gatinho de névoa',mist_rabbit_cute:'Coelho de nuvem',mist_fox_cute:'Raposa azul',
 ocean_turtle_cute:'Tartaruga',ocean_shark_cute:'Tubarão',ocean_dolphin_cute:'Golfinho',ocean_octopus_cute:'Polvo',ocean_whale_cute:'Baleia',ocean_clownfish_cute:'Peixe-palhaço',
 space_alien_cute:'ET',space_robot_cute:'Robô',space_cat_cute:'Gato cósmico',
 forest_wolf_cute:'Lobo',forest_fox_cute:'Raposa',forest_tiger_cute:'Tigre',
 solar_lion_cute:'Leão solar',solar_dragon_cute:'Dragão solar',solar_phoenix_cute:'Fênix',
 coral_axolotl_cute:'Axolote',coral_octopus_cute:'Polvo',coral_seahorse_cute:'Cavalo-marinho'
 };return m[x]||'Pet'
}
function r152AccLabel(x){
 const suffix=x.split('_').slice(-1)[0],m={cap:'Cabeça',collar:'Pescoço',glasses:'Rosto',backpack:'Corpo/costas',badge:'Medalhão',special:'Especial'};
 return m[suffix]||'Acessório'
}
function r152AllCycles(){return r147jget(R152_CYCLES,{})}
function r152SaveAllCycles(v){r147jset(R152_CYCLES,v)}
function r152Box(mid){const all=r152AllCycles();if(!all[mid])all[mid]={current:null,history:[]};if(!Array.isArray(all[mid].history))all[mid].history=[];return {all,box:all[mid]}}
function r152NewCycle(mid){
 const {box}=r152Box(mid),theme='ocean',t=r152Themes()[theme],used=new Set(box.history.map(h=>h.pet));
 const pet=t.pets.find(p=>!used.has(p))||t.pets[0];
 return {id:'cy_'+Date.now(),number:box.history.length+1,theme,pet,accessories:t.acc.slice(0,5),pointsPerStep:20,medalsPerAccessory:3,createdAt:Date.now(),status:'active'}
}
function r152EnsureCycle(mid){const {all,box}=r152Box(mid);if(!box.current){box.current=r152NewCycle(mid);all[mid]=box;r152SaveAllCycles(all)}return box.current}
function r152Progress(mid){
 const c=r152EnsureCycle(mid),p=loadKidsProgress()[mid]||{lifetime:0,log:[]},u=Math.floor((+p.lifetime||0)/Math.max(1,+c.pointsPerStep||20));
 const phases=['Bronze','Prata','Ouro','Troféu','Super Troféu','Cápsula','Acessórios'],idx=Math.min(6,u);
 const a=Math.min(c.accessories.length,Math.floor(Math.max(0,u-6)/Math.max(1,+c.medalsPerAccessory||3)));
 const now=Date.now(),day=86400000,active=new Set((p.log||[]).map(x=>+x.at||+x.timestamp||0).filter(t=>t&&now-t<=14*day).map(t=>new Date(t).toISOString().slice(0,10)));
 return {c,p,idx,phase:phases[idx],acc:a,active:active.size,missed:14-active.size,next:idx<6?phases[idx+1]:(a<c.accessories.length?`Acessório ${a+1}`:'Próximo ciclo')}
}
function r152KidsPanel(mid){
 const m=satelliteMember(mid),pr=r152Progress(mid),c=pr.c,t=r152Themes()[c.theme],hist=r152Box(mid).box.history||[],used=new Set(hist.map(h=>h.pet));
 return `<section class="r152-kid-overview">
   <section class="r147-card"><div class="r147-head"><div><h3>${r147esc(m?.name||'Kids')}</h3><p>Ciclo de Progressão ${c.number} · visão do Owner</p></div><select id="r152KidSel">${(loadSatellites().members||[]).filter(x=>x.role==='kids'&&x.status!=='removed').map(k=>`<option value="${k.id}" ${String(k.id)===String(mid)?'selected':''}>${r147esc(k.name)}</option>`).join('')}</select></div>
   <div class="r152-current"><div class="r152-pet-hero">${r147img(c.pet)}<span><strong>${r147esc(r152PetLabel(c.pet))}</strong><small>${r147esc(t.name)} · pet-alvo</small></span></div><div class="r152-stats"><div><small>Fase</small><strong>${r147esc(pr.phase)}</strong></div><div><small>Pontos</small><strong>${+pr.p.lifetime||0}</strong></div><div><small>Acessórios</small><strong>${pr.acc}/${c.accessories.length}</strong></div><div><small>Próximo</small><strong>${r147esc(pr.next)}</strong></div></div><div class="r152-activity"><span>${pr.active} dias ativos</span><span>${pr.missed} sem missão</span></div></div></section>
   <section class="r147-card"><div class="r147-head"><div><h3>Configurar ciclo</h3><p>Escolha o universo, o pet, as metas e os itens daquele pet. O tabuleiro completo ficará no Satélite Kids.</p></div></div>
   <div class="r152-form-grid"><label>Tema<select id="r152Theme">${Object.entries(r152Themes()).map(([k,v])=>`<option value="${k}" ${k===c.theme?'selected':''}>${v.name}</option>`).join('')}</select></label><label>Pet<select id="r152Pet">${t.pets.map(p=>`<option value="${p}" ${p===c.pet?'selected':''}>${r147esc(r152PetLabel(p))}${used.has(p)?' · já conquistado':''}</option>`).join('')}</select></label><label>Pontos por marco<input id="r152Pts" type="number" min="1" value="${c.pointsPerStep}"></label><label>Medalhas por acessório<input id="r152Medals" type="number" min="1" value="${c.medalsPerAccessory}"></label></div>
   <div class="r152-theme-preview"><div class="r152-capsule">${r147img(t.capsule)}<small>Cápsula ${t.name}</small></div><div class="r152-pets">${t.pets.map(p=>`<button type="button" data-r152pet="${p}" class="${p===c.pet?'active':''} ${used.has(p)?'used':''}"><span>${r147img(p)}</span><strong>${r147esc(r152PetLabel(p))}</strong><small>${used.has(p)?'já conquistado':'disponível'}</small></button>`).join('')}</div></div>
   <div class="r152-accessories"><div><strong>Acessórios do pet</strong><small>Cada tema tem um rol próprio. Você escolhe quais entram neste ciclo.</small></div><div class="r152-acc-grid">${t.acc.map(a=>`<label class="${c.accessories.includes(a)?'active':''}"><input type="checkbox" data-r152acc="${a}" ${c.accessories.includes(a)?'checked':''}><span>${r147img(a)}</span><strong>${r147esc(r152AccLabel(a))}</strong></label>`).join('')}</div></div>
   <button class="primary" id="r152SaveCycle">Salvar ciclo</button></section>
   <section class="r147-card"><div class="r147-head"><div><h3>Histórico de ciclos</h3><p>Mostra o caminho já percorrido e impede repetir pet sem perceber.</p></div><button class="r147-action" id="r152FinishCycle">Concluir ciclo</button></div><div class="r152-history">${hist.length?hist.slice().reverse().map(h=>`<div class="r152-hist-row"><span>${r147img(h.pet)}</span><div><strong>Ciclo ${h.number} · ${r147esc(r152Themes()[h.theme]?.name||h.theme)}</strong><small>${r147esc(r152PetLabel(h.pet))} · concluído</small></div></div>`).join(''):'<div class="sat-empty">Nenhum ciclo concluído ainda.</div>'}</div></section>
 </section>`
}
function r152WireKids(){
 const sel=document.querySelector('#r152KidSel');if(!sel)return;
 const render=()=>renderRewardsRC152('kids');
 sel.onchange=()=>{window.berthaHmlStorage.setItem('bertha.rewards.selected.kid',sel.value);render()};
 document.querySelector('#r152Theme')?.addEventListener('change',e=>{
   const mid=sel.value,{all,box}=r152Box(mid),c=box.current||r152NewCycle(mid),t=r152Themes()[e.target.value],used=new Set(box.history.map(h=>h.pet));
   c.theme=e.target.value;c.pet=t.pets.find(p=>!used.has(p))||t.pets[0];c.accessories=t.acc.slice(0,5);box.current=c;all[mid]=box;r152SaveAllCycles(all);render()
 });
 document.querySelectorAll('[data-r152pet]').forEach(b=>b.onclick=()=>{const {all,box}=r152Box(sel.value);box.current=r152EnsureCycle(sel.value);box.current.pet=b.dataset.r152pet;all[sel.value]=box;r152SaveAllCycles(all);render()});
 document.querySelector('#r152SaveCycle')?.addEventListener('click',e=>{
   const mid=sel.value,{all,box}=r152Box(mid),c=box.current||r152NewCycle(mid);
   c.theme=document.querySelector('#r152Theme').value;c.pet=document.querySelector('#r152Pet').value;c.pointsPerStep=Math.max(1,+document.querySelector('#r152Pts').value||20);c.medalsPerAccessory=Math.max(1,+document.querySelector('#r152Medals').value||3);c.accessories=[...document.querySelectorAll('[data-r152acc]:checked')].map(x=>x.dataset.r152acc);box.current=c;all[mid]=box;r152SaveAllCycles(all);
   e.currentTarget.textContent='Salvo';setTimeout(()=>e.currentTarget.textContent='Salvar ciclo',800)
 });
 document.querySelector('#r152FinishCycle')?.addEventListener('click',()=>{const mid=sel.value,{all,box}=r152Box(mid),c=box.current||r152NewCycle(mid);box.history.push({...c,status:'complete',completedAt:Date.now()});box.current=null;all[mid]=box;r152SaveAllCycles(all);render()})
}

/* Owner pins */
function r152OwnerPins(){
 const ownerPane=document.querySelector('[data-r147pane="owner"]');if(!ownerPane)return;
 const first=ownerPane.querySelector('.r147-card');if(first){
   const cards=first.querySelectorAll('.r147-ach .art'),imgs=['pin_constancy','pin_cycle','pin_focus','pin_selfcare'];cards.forEach((x,i)=>{if(imgs[i])x.innerHTML=r147img(imgs[i])});
 }
 const room=[...ownerPane.querySelectorAll('.r147-card')].find(x=>x.querySelector('h3')?.textContent?.includes('Sala de Troféus ·'));
 if(room&&!room.querySelector('.r152-pin-note')){
   const n=document.createElement('div');n.className='r152-pin-note';n.innerHTML='<strong>Coleção de pins BERTH.A</strong><small>Conquistas cumulativas com variação de cor por ciclo/mês.</small>';room.appendChild(n)
 }
}
r147OwnerCollection=function(){
 const items=[['pin_constancy','Constância','7 dias'],['pin_cycle','Ciclo concluído','rotina ou projeto'],['pin_focus','Foco','30 dias'],['pin_balance','Equilíbrio','semana alinhada'],['pin_goal','Meta alcançada','objetivo concluído'],['pin_presence','Presença','ritual mantido'],['pin_sequence','Sequência','novo marco'],['pin_delivery','Projeto entregue','etapa importante'],['pin_continuity','Continuidade','ciclo renovado'],['pin_selfcare','Autocuidado','escolha consciente'],['pin_depth','Profundidade','foco sustentado'],['pin_evolution','Evolução','histórico pessoal']];
 r147Dialog('Sala de Troféus',`<div class="r152-pin-intro"><strong>Sua coleção de pins</strong><small>Sem imagens Kids: uma vitrine de conquistas pessoais.</small></div><div class="r147-collection">${items.map((x,i)=>`<div class="r147-col-item">${r147img(x[0])}<strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}</div>`)
}

/* Rewards renderer: Owner + Helper da base; Kids substituído pelo painel de ciclo. */
const _r152BaseRewards=_r150RewardsBase;
function renderRewardsRC152(forceTab=''){
 _r152BaseRewards(forceTab);
 r150OwnerEnhance();r152OwnerPins();
 const kidsPane=document.querySelector('[data-r147pane="kids"]');
 if(kidsPane){
   const kids=(loadSatellites().members||[]).filter(m=>m.status!=='removed'&&m.role==='kids');
   if(kids.length){
     let mid=window.berthaHmlStorage.getItem('bertha.rewards.selected.kid')||kids[0].id;
     if(!kids.some(k=>String(k.id)===String(mid)))mid=kids[0].id;
     kidsPane.innerHTML=r152KidsPanel(mid);r152WireKids()
   }else kidsPane.innerHTML='<section class="r147-card"><div class="sat-empty">Cadastre um satélite como Kids para configurar um Ciclo de Progressão.</div></section>'
 }
 const activate=(name)=>{document.querySelectorAll('[data-r147tab]').forEach(b=>b.classList.toggle('active',b.dataset.r147tab===name));document.querySelectorAll('[data-r147pane]').forEach(p=>p.hidden=p.dataset.r147pane!==name)};
 document.querySelectorAll('[data-r147tab]').forEach(b=>b.onclick=()=>activate(b.dataset.r147tab));
 activate(forceTab||'owner')
}
renderRewardsRC147=renderRewardsRC152;renderUniversalRewards=renderRewardsRC152;renderKidsRewards=renderRewardsRC152;

