/* ============================================================
   RC154 — camada autoritativa final
   ============================================================ */
(function(){
  // Any legacy rewards timeout still alive must render ONLY the final renderer.
  try{
    renderRewardsRC141 = renderRewardsRC152;
    renderRewardsRC143 = renderRewardsRC152;
    renderRewardsRC144 = renderRewardsRC152;
    renderRewardsRC147 = renderRewardsRC152;
    renderUniversalRewards = renderRewardsRC152;
    renderKidsRewards = renderRewardsRC152;
  }catch(e){ console.warn('RC154 reward aliases',e); }

  // Render the current route exactly once per explicit navigation,
  // then once more on the next animation frame to settle late layout code.
  window.__berthaOpenRoute154=function(route){
    const dlg=document.getElementById('moduleMenu');
    if(dlg?.open) dlg.close();
    state.route=route;
    document.body.dataset.berthaRoute=route;
    try{history.replaceState({berthaRoute:route},'',location.pathname+location.search+'#'+route)}catch{}
    window.__berthaCoreRender?.();
    requestAnimationFrame(()=>window.__berthaCoreRender?.());
  };

  // Fixed build badge: if this badge is visible, RC154 is truly running.
  const st=document.createElement('style');
  st.id='rc154-build-style';
  st.textContent=`
    .rc154-build{
      position:fixed;z-index:999999;right:10px;
      top:calc(env(safe-area-inset-top,0px) + 8px);
      padding:5px 9px;border-radius:999px;
      background:#443d49;color:#fff;
      font-size:8px;letter-spacing:.09em;
      box-shadow:0 3px 12px rgba(60,50,64,.14);
      pointer-events:none
    }`;
  document.head.appendChild(st);
  const badge=document.createElement('div');
  badge.className='rc154-build';
  badge.textContent='HML · RC169';
  document.body.appendChild(badge);
  document.documentElement.dataset.berthaBuild='RC157';

  // On page restore (Safari back/forward cache), repaint only the active route.
  window.addEventListener('pageshow',()=>{
    requestAnimationFrame(()=>window.__berthaCoreRender?.());
  });
})();

/* RC156 — integração com o módulo Satélites reconstruído. */
const __rc156CoreRender = window.__berthaCoreRender;
window.__berthaCoreRender = function(){
  const route=(location.hash||'').replace('#','')||state.route||'meu-dia';
  if(route==='satelites' && typeof window.renderSatellitesV156==='function'){
    state.route='satelites';document.body.dataset.berthaRoute='satelites';
    return window.renderSatellitesV156();
  }
  if(route==='satelite' && typeof window.renderSatelliteProfileV156==='function'){
    state.route='satelite';document.body.dataset.berthaRoute='satelite';
    return window.renderSatelliteProfileV156();
  }
  return __rc156CoreRender?.();
};

/* ============================================================
   RC158 — CONSOLIDAÇÃO DE PREMIAÇÕES
   Base funcional congelada: RC157
   ============================================================ */
(function(){
  const finalRewards =
    (typeof renderRewardsRC152==='function' && renderRewardsRC152) ||
    (typeof renderRewardsRC147==='function' && renderRewardsRC147) ||
    (typeof renderUniversalRewards==='function' && renderUniversalRewards) ||
    null;

  if(finalRewards){
    try{ renderRewardsRC141 = finalRewards; }catch{}
    try{ renderRewardsRC143 = finalRewards; }catch{}
    try{ renderRewardsRC144 = finalRewards; }catch{}
    try{ renderRewardsRC147 = finalRewards; }catch{}
    try{ renderUniversalRewards = finalRewards; }catch{}
    try{ renderKidsRewards = finalRewards; }catch{}
    window.__berthaFinalRewardsRenderer = finalRewards;
  }

  window.__BERTHA_REWARD_ASSETS_V158__ = {
    ownerPins:['pin_constancy','pin_cycle','pin_focus','pin_balance','pin_goal','pin_presence'],
    helperRecognitions:[
      'recognition_coffee','recognition_dinner','recognition_family',
      'recognition_flower','recognition_gift','recognition_heart'
    ],
    kidsThemes:['mist','ocean','space','forest','solar','coral']
  };

  document.documentElement.dataset.berthaBuild='RC158';
})();
